
package com.camtv.tv; import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; public class BootReceiver extends BroadcastReceiver { @Override public void onReceive(Context context, Intent intent) { if (intent == null) { return; } String action = intent.getAction(); if (Intent.ACTION_BOOT_COMPLETED.equals(action)) { Intent serviceIntent = new Intent(context, MonitorService.class); context.startService(serviceIntent); Intent activityIntent = new Intent(context, MainActivity.class); activityIntent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK); context.startActivity(activityIntent); } } }
